import java.util.Scanner;

public class Main {
    private static final class Solver {
        private final String s;
        private final int n;

        Solver(String str, int length) {
            s = str;
            n = length;
        }

        int maxLengthOutside() {
            int max = -1;
            int cur = 0;
            for (int i = 0; i < n; i++) {
                char c = s.charAt(i);
                if (c == '_') {
                    if (cur > max) max = cur;
                    cur = 0;
                } else if (c != '(' && c != ')') {
                    cur++;
                } else {
                    if (cur > max) max = cur;
                    cur = 0;
                    i++;
                    while (s.charAt(i) != ')') {
                        i++;
                    }
                }
            }
            if (cur > max) max = cur;
            return max;
        }

        int countWordsInParentheses() {
            int words = 0;
            int cur = 0;
            for (int i = 0; i < n; i++) {
                while (i < n && s.charAt(i) != '(') {
                    i++;
                }
                if (i == n) {
                    break;
                }
                i++;
                while (s.charAt(i) != ')') {
                    if (s.charAt(i) == '_') {
                        if (cur > 0) {
                            words++;
                        }
                        cur = 0;
                    } else {
                        cur++;
                    }
                    i++;
                }
                if (cur > 0) {
                    words++;
                }
                cur = 0;
            }
            return words;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        String input = sc.next();
        Solver solver = new Solver(input, n);
        System.out.println(solver.maxLengthOutside() + " " + solver.countWordsInParentheses());
    }
}
